// Types for the variables injected from .env by react-native-dotenv
declare module '@env' {
  export const DEFAULT_CATALOG_URL: string | undefined;
  export const GOOGLE_DRIVE_API_KEY: string | undefined;
  export const GOOGLE_OAUTH_CLIENT_ID: string | undefined;
  export const GOOGLE_OAUTH_CLIENT_SECRET: string | undefined;
  export const GOOGLE_OAUTH_REFRESH_TOKEN: string | undefined;
  export const UPDATE_MANIFEST_URL: string | undefined;
}
